import{_ as a,o,c as s,a6 as t}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"Use o TikTools","description":"","frontmatter":{"title":"Use o TikTools","docId":"user.overview","translationKey":"user.overview","locale":"pt","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"72ce37218d4f3341fccd306bd0b1b4039ec6e1fd3dcfeb16f9096f43576c861d","translationRevision":"b0a5dae8327c90d38643e673c7d2e1068f3f768c380f77b436bc64eb029fc554","order":0},"headers":[],"relativePath":"pt/user/index.md","filePath":"pt/user/index.md","lastUpdated":1794611623000}'),i={name:"pt/user/index.md"};function r(n,e,d,l,c,u){return o(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="use-tiktools" tabindex="-1">Use o TikTools <a class="header-anchor" href="#use-tiktools" aria-label="Permalink to &quot;Use o TikTools {#use-tiktools}&quot;">​</a></h1><p>O TikTools conecta um desktop Windows ou Linux a uma LIVE do TikTok, exibe seus eventos, mantém pontos dos espectadores e executa regras no seu computador. A interface de desktop e o host opcional sem interface gráfica compartilham o mesmo núcleo Rust. Uma conta do Cloud é independente da conexão com o TikTok.</p><h2 id="choose-your-first-task" tabindex="-1">Escolha sua primeira tarefa <a class="header-anchor" href="#choose-your-first-task" aria-label="Permalink to &quot;Escolha sua primeira tarefa {#choose-your-first-task}&quot;">​</a></h2><ol><li>Confira os <a href="./requirements.html">requisitos</a> e <a href="./installation.html">instale um binário publicado</a>. Você não precisa de Rust, Cargo ou Bun para usar a versão de desktop.</li><li><a href="./first-live.html">Conecte-se a uma LIVE</a>, começando sem cookie do TikTok quando a sala permitir acesso de visitante.</li><li>Use <strong>Live feed</strong> para inspecionar eventos. <strong>Points</strong> mantém os totais dos espectadores; <strong>Analytics</strong> mostra estatísticas. <strong>Automations</strong> conecta acionadores a ações configuradas.</li><li>Instale integrações opcionais em <strong>Plugins</strong>. Os pacotes de plugins externos são distribuídos separadamente do aplicativo.</li><li>Use <strong>Overlays</strong> para preparar uma fonte de navegador no OBS. A integração com o gateway é necessária para entregar widgets ao vivo.</li></ol><h2 id="available-and-experimental-features" tabindex="-1">Recursos disponíveis e experimentais <a class="header-anchor" href="#available-and-experimental-features" aria-label="Permalink to &quot;Recursos disponíveis e experimentais {#available-and-experimental-features}&quot;">​</a></h2><p>A navegação principal expõe Live feed, Points, Analytics, Connections, Automations, Plugins, Overlays e Settings. Rankings e competições têm um mecanismo nativo e uma rota direta, mas sua página de gerenciamento ainda está oculta na navegação normal. Não presuma que todo protótipo descrito em um documento de projeto antigo seja um recurso lançado.</p><p>Alterações de plugins do Cloud e Variables revisadas usam controles explícitos por seção. Automations atualmente compara com uma cópia de referência local; esse botão não publica perfis no Cloud. Os transportes de colaboração e alguns encaminhamentos para instaladores continuam experimentais. Um controle desativado normalmente indica uma capacidade ausente no host ou um pré-requisito não atendido.</p><h2 id="when-something-fails" tabindex="-1">Quando algo falha <a class="header-anchor" href="#when-something-fails" aria-label="Permalink to &quot;Quando algo falha {#when-something-fails}&quot;">​</a></h2><p>Abra <strong>Diagnostics</strong>, guarde a origem do erro e o identificador da solicitação e registre a versão instalada do aplicativo. Evite incluir cookies, tokens de convite ou valores de variáveis privadas. Comece pelas instruções de recuperação de cada guia e depois consulte os guias de suporte. A demonstração interativa usa dados fictícios e não pode determinar se sua conta do TikTok, o OBS ou a rede funcionam.</p><p>Para desenvolver o código-fonte, use a <a href="./../developer/">documentação de desenvolvimento</a> separada.</p>',10)])])}const f=a(i,[["render",r]]);export{m as __pageData,f as default};
